exp1"]={["arg1"]=[[玩家武功经验变化]],["arg2"]=[[duanzaozhishu]],["arg3"]=1,["id"]=[[rlt_sbskillexp1]]},["rlt_sbtankuang1"]={["arg1"]=[[弹出选项框]],["arg2"]=[[YEL唐不平：我从媛儿那听说了一切。少侠的恩情，无以为报。既然少侠为我们出生入死，便不是外人。我可以将唐门的恩怨往事都告诉你，你可愿一听？]],["arg3"]=[[听]],["arg4"]=[[不听]],["arg5"]=[[sbgushi1;sbchange12]],["arg6"]=[[sbtext3]],["id"]=[[rlt_sbtankuang1]]},["rlt_sbtext1"]={["arg1"]=[[文本输出]],["arg2"]=[[此人见敌不过你，虚晃一招，纵身离开。]],["id"]=[[rlt_sbtext1]]},["rlt_sbtext10"]={["arg1"]=[[副本故事]],["arg2"]=[[欧冶子将轩辕夏带来的两把剑拿起，轻轻摇了摇头。;HIC欧冶子：唐门既然将轩辕家锻造术传授于你，那你日后便是轩辕家的传人了，锻造之道十分深奥，老夫还需教你几手。]],["arg3"]=3,["id"]=[[rlt_sbtext10]]},["rlt_sbtext11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐元枫：唐门遭逢巨变，还请少侠施以援手。若少侠有意相助，便拿着这枚唐门密令来唐门禁地找我便可，大恩大德，感激不尽。]],["id"]=[[rlt_sbtext11]]},["rlt_sbtext12"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐元枫：唐门遭逢巨变，还请少侠施以援手。若少侠有意相助，来唐门禁地找我便可，大恩大德，感激不尽。]],["id"]=[[rlt_sbtext12]]},["rlt_sbtext13"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐元媛：这手绢是哥哥让你送来的？谢谢你。神医，劳烦您看看。]],["id"]=[[rlt_sbtext13]]},["rlt_sbtext14"]={["arg1"]=[[文本输出]],["arg2"]=[[你们正在缠斗，只觉得熟悉的青衣一闪，随即一人突然杀出，双剑直取唐不武面门！]],["id"]=[[rlt_sbtext14]]},["rlt_sbtext15"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐怀德：哼，小子，今日让你有来无回！]],["id"]=[[rlt_sbtext15]]},["rlt_sbtext16"]={["arg1"]=[[文本输出]],["arg2"]=[[唐怀义：快，都给我上！给我拿下他！]],["id"]=[[rlt_sbtext16]]},["rlt_sbtext17"]={["arg1"]=[[文本输出]],["arg2"]=[[唐不平：唐家人虽然随老二作乱，但终究是迫于他的淫威，我若出面，自然能收归人心。只是唐门上下除了我没人能制住他，我如今伤势还未痊愈，却不知道如何是好。
欧冶子：无妨，我与你同去，老夫对武器颇有些心得，想必能看穿他招式之间的破绽。
唐元枫：我也去！]],["id"]=[[rlt_sbtext17]]},["rlt_sbtext18"]={["arg1"]=[[副本故事]],["arg2"]=[[CYN轩辕夏：唐门的老贼！你害死我轩辕全家，又害死沐前辈全家，如今新仇旧恨，一并找你们算上！;唐不武：你不妨试试。;CYN轩辕夏怒喝一声，左右各执一剑，挥舞之下呼啸有声，唐不武抽身，手中绿芒连闪直袭轩辕夏胸口，轩辕夏躲闪不及，只得举剑相迎，只听得当啷巨响，那暗器竟然洞穿剑身，打入轩辕夏右肩之中。]],["arg3"]=[[3;3]],["id"]=[[rlt_sbtext18]]},["rlt_sbtext2"]={["arg1"]=[[文本输出]],["arg2"]=[[通往二楼的门紧锁着。]],["id"]=[[rlt_sbtext2]]},["rlt_sbtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[唐不平：少侠想听再告诉我吧。]],["id"]=[[rlt_sbtext3]]},["rlt_sbtext4"]={["arg1"]=[[文本输出]],["arg2"]=[[唐怀德见不敌，转身逃离。]],["id"]=[[rlt_sbtext4]]},["rlt_sbtext5"]={["arg1"]=[[文本输出]],["arg2"]=[[唐怀义见不敌，转身逃离。]],["id"]=[[rlt_sbtext5]]},["rlt_sbtext6"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN轩辕夏：咳..
唐不武：好啊，原来一直是你在暗中捣鬼。如今你身中毒镖，活不过半刻。想杀我？去死吧！
CYN唐不武说着，伸掌就要对轩辕夏天灵盖打去，只听得半空中风声呼啸，另一人掌风凌厉地将唐不武手掌隔开。]],["id"]=[[rlt_sbtext6]]},["rlt_sbtext7"]={["arg1"]=[[文本输出]],["arg2"]=[[唐不平虽然将唐不武打成重伤，但毙命一掌终究迟迟没有拍下，最终给唐不武趁机逃走了。]],["id"]=[[rlt_sbtext7]]},["rlt_sbtext8"]={["arg1"]=[[文本输出]],["arg2"]=[[唐不平落败。]],["id"]=[[rlt_sbtext8]]},["rlt_sbtext9"]={["arg1"]=[[副本故事]],["arg2"]=[[CYN唐不平：你父母虽非我杀，但终究是因我而死。轩辕家的锻造术在我这保管多年，如今也该物归原主了。你若是心怀怨恨，此时取我性命，我也绝无怨言。;轩辕夏：咳…我反正活不了了。可恨，可恨我没有报仇，可恨我轩辕家，就此..;轩辕夏气息逐渐微弱，渐渐便再也听不见声响。]],["arg3"]=[[3;3]],["id"]=[[rlt_sbtext9]]},["rlt_sbtextbox1"]={["arg1"]=[[弹出文本窗口]],["arg3"]=[[欧冶子前辈为沐前辈一事而来，而沐前辈确为我唐门中人所杀。
昔年江湖动乱，神兵利器为人人所趋鹜，铸剑师也最受人尊敬。
除了超然于世的欧冶子前辈，江湖上还有三名颇有名气的铸剑师，名为西绝华山沐清风。南隐唐门唐阡陌，北水之巅轩辕生。”
这指的便是沐清风，我父亲唐阡陌与轩辕生。单论锻造技艺而言，他三人各有所长，相互争斗多年分不出高下，竟成为生死与共的好友。后来他们都有了子嗣，便决定让后代来一决高低。
父亲带去的子嗣便是我。另外则是沐前辈之子沐桓，轩辕前辈之子轩辕清。三月之后各自铸成，沐桓铸软剑千无；我在剑之上加入了唐门的机关术，铸造机关剑含影；而轩辕清铸造出了两把短剑，以两子之名命曰云霞、东来。
三剑对决，终是我唐门侥幸略胜一筹，却不想被轩辕生看出破绽与我父亲发生争执。我也是从他们对话中得知，父亲传授给我的铸造术中融合了轩辕家的独门锻造术，而轩辕清的妻子，恰好是我唐门中人。轩辕生骂我父亲全然不顾相识一场，派唐门人故意接近轩辕家，偷学轩辕家的铸造术，而父亲也并没有否认。争执当晚，轩辕清与他妻子竟被发现死在客栈中，而所有证据却都指向我唐门。轩辕生气得来与我父亲拼命，我父亲的暗器竟然被人暗中淬了毒，失手伤了轩辕生之后，他便殒命当场。
轩辕家一晚惨遭横祸，只留下最小的孩子幸存，沐前辈却相信轩辕家的人并非我爹所杀，并未发难，只是将轩辕清的剑与那孩子一同带回华山。
轩辕家虽然并非父亲亲手所害，却也是因为父亲派人盗走轩辕家铸造术才会引发误会，因而他回到唐门便将门主让给我，不再管理家中之事，也不再允许唐门人学习铸造技艺。
后来我仔细调查此事，才发现嫁祸于父亲的竟然不是别人，正是我二弟，唐不武。他觊觎门主之位，本想借着嫁祸父亲与我来除掉我们，没想到这事最终被按下不提。我知道他心怀不轨，却念在兄弟之情终究下不去手，老二却暗中经营多年，如今乘着父亲病逝，对我下毒暗算，又让自己的手下占领了唐门。他怕当年嫁祸轩辕家的事会东窗事发，便派人害死了 知晓部分实情的沐家父子，轩辕家的遗子也不知道有没有被他害死。]],["id"]=[[rlt_sbtextbox1]]},["rlt_sbtextout1"]={["arg1"]=[[弹出文本]],["arg2"]=[[机关师拦住了你。]],["id"]=[[rlt_sbtextout1]]},["rlt_sbtextout2"]={["arg1"]=[[弹出文本]],["arg2"]=[[唐怀德拦住了你。]],["id"]=[[rlt_sbtextout2]]},["rlt_sbtextout3"]={["arg1"]=[[弹出文本]],["arg2"]=[[鹰组武士拦住了你。]],["id"]=[[rlt_sbtextout3]]},["rlt_sbtextout4"]={["arg1"]=[[弹出文本]],["arg2"]=[[犬组武士拦住了你。]],["id"]=[[rlt_sbtextout4]]},["rlt_sbtextout5"]={["arg1"]=[[弹出文本]],["arg2"]=[[唐怀义拦住了你。]],["id"]=[[rlt_sbtextout5]]},["rlt_sbtextout6"]={["arg1"]=[[弹出文本]],["arg2"]=[[此物你已获得过。]],["id"]=[[rlt_sbtextout6]]},["rlt_sbtextout7"]={["arg1"]=[[弹出文本]],["arg2"]=[[唐门之乱已完成，神兵新系统已开启，请回主界面查看。]],["id"]=[[rlt_sbtextout7]]},["rlt_sbtextout8"]={["arg1"]=[[文本输出]],["arg2"]=[[HIW欧冶子已云游四方去了，日后若是有缘可寻得其踪迹。]],["id"]=[[rlt_sbtextout8]]},["rlt_sbtextout9"]={["arg1"]=[[弹出文本]],["id"]=[[rlt_sbtextout9]]},["rlt_skill1"]={["arg1"]=[[玩家属性变化]],["arg2"]=[[jibenjianfa]],["arg3"]=1,["id"]=[[rlt_skill1]]},["rlt_stop"]={["arg1"]=[[阻止玩家移动]],["id"]=[[rlt_stop]]},["rlt_tangmenzhiluandonghua1"]={["arg1"]=[[唐门之乱播放动画]],["id"]=[[rlt_tangmenzhiluandonghua1]]},["rlt_text1"]={["arg1"]=[[文本输出]],["arg2"]=[[茶客乙：听说萧红叶萧大侠被唐门抓起来了，什么情况。
茶客甲：听说说萧红叶触怒了唐不平，啧啧，一代大侠居然也落得如此下场。]],["id"]=[[rlt_text1]]},["rlt_text10"]={["arg1"]=[[文本输出]],["arg2"]=[[TEL唐英：你居然能打败唐不平，真有你的，你能不能帮我一个忙。]],["id"]=[[rlt_text10]]},["rlt_text11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐甜：好小子，放走我唐门犯人居然还敢进我唐门，来人啊！]],["id"]=[[rlt_text11]]},["rlt_text1100"]={["arg1"]=[[文本输出]],["arg2"]=[[洛还君敌不过你，转身逃走时被你眼疾手快抢到了木牌。]],["id"]=[[rlt_text1100]],["jobstart"]=[[fb23rw08]]},["rlt_text1101"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐胜：有本事你给我等着！我这就去叫人！]],["id"]=[[rlt_text1101]],["jobstart"]=[[fb23rw08]]},["rlt_text1102"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text1102]]},["rlt_text1103"]={["arg1"]=[[文本输出]],["id"]=[[rlt_text1103]]},["rlt_text12"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL唐甜：哼，你当我唐门是什么地方！这是我唐门三大高手，你若能胜过他们，这事咱们就一笔勾销。]],["id"]=[[rlt_text12]]},["rlt_text1200"]={["arg1"]=[[文本输出]],["arg2"]=[[唐管家：给我拿下这个冒充少主的人！
